#!/usr/bin/env python3
import time
import pickle
import numpy as np
from pathlib import Path
from pd.runtime import API
from pd.common.onnx_infer import OnnxInfer
from pd.prm import PolyReferenceMotion
import logging

# Configure logging
logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)

HOME_DIR = Path.home()

class RLSimWalk(object):
    def __init__(
        self,
        onnx_model_path: str,
        serial_port: str = "/dev/puddleduck_ctrl",
        playback_hz: float = 1.0,       # Hz for stepping through sim obs
        action_scale=0.25,
        vel_scale: float = 0.05,
        save_obs=False,
        replay_obs_path=None,
    ):
        # must have sim observations
        if replay_obs_path is None:
            raise ValueError("This script only works in playback mode; --replay_obs is required")
        # load list of {'obs': ..., 'action': ...} pairs
        self.replay_pairs = pickle.load(open(replay_obs_path, "rb"))
        self.replay_index = 0

        # hardware API (to drive real motors and stream joint readings)
        self.api = API(serial_port)

        # timing parameters
        self.playback_dt = 1.0 / playback_hz
        # ensure movement completes before next obs
        self.move_duration = self.playback_dt / 2

        # ONNX policy
        self.policy = OnnxInfer(onnx_model_path, awd=True)

        # for reference motion length (unused for phase now)
        self.PRM = PolyReferenceMotion(HOME_DIR / 'polynomial_coefficients.pkl')

        # initial joint pose (absolute)
        self.init_pos = np.array([
            0.0314, 0.0303, 1.0330, -1.1882, 0.3975,
            -0.0298, -0.0273, -0.9512, -1.1753, -0.4634
        ])

        # scales
        self.action_scale = action_scale
        self.vel_scale = vel_scale

        # history for smoothing (optional)
        self.last_action = np.zeros(10)
        self.last_last_action = np.zeros(10)
        self.last_last_last_action = np.zeros(10)

        # to record results
        self.save_obs = save_obs
        if self.save_obs:
            self.saved_pairs = []

        logger.info(f"[RLSimWalk] loaded {len(self.replay_pairs)} sim observations, ONNX providers: {self.policy.get_providers()}")

    def handle_observation(self, hwobs):
        """Called on each hardware OBS message; consumes one sim OBS."""
        if self.replay_index >= len(self.replay_pairs):
            logger.info("[RLSimWalk] all sim observations played back; stopping")
            return False

        current_index = self.replay_index
        # get next saved obs/action pair
        entry = self.replay_pairs[self.replay_index]
        obs_sim = entry['obs']
        action_sim = entry['action']
        motor_target_sim = entry['motor']
        self.replay_index += 1

        # extract sim IMU (gyro + accel), sim commands, sim imitation_phase
        imu_sim = obs_sim[0:6]
        cmd_sim = obs_sim[6:9]
        dof_pos_sim = obs_sim[9:19]
        dof_vel_sim = obs_sim[19:29]
        phase_sim = obs_sim[-2:]

        # read hardware joints
        dof_pos = np.array(np.around(hwobs.joint_angles, 5))
        dof_vel = np.array(np.around(hwobs.joint_vel, 5))

        # assemble observation for policy: mix sim IMU/commands/phase + real joint data
        obs_hw = np.concatenate([
            imu_sim,
            cmd_sim,
            dof_pos - self.init_pos,
            dof_vel * self.vel_scale,
            self.last_action,
            self.last_last_action,
            self.last_last_last_action,
            self.init_pos + self.last_action * self.action_scale,  # last motor targets
            phase_sim,
        ])

        # infer action and update history
        action_hw = self.policy.infer(obs_hw)
        self.last_last_last_action = self.last_last_action.copy()
        self.last_last_action      = self.last_action.copy()
        self.last_action           = action_hw.copy()

        # compute new targets and send to hardware
        motor_target_hw = self.init_pos + action_sim * self.action_scale

        # use sim motor target 
        targets = self.init_pos + dof_pos_sim
        self.api.policyAction("default", joint_radians=targets, duration=self.move_duration)

        # record sim vs hardware observation for later comparison
        if self.save_obs:
            self.saved_pairs.append({
                'obs_sim': obs_sim.copy(),
                'obs_hw':  obs_hw.copy(),
                'action_sim':  action_sim.copy(),
                'action_hw':  action_hw.copy(),
                'motor_sim':  motor_target_sim.copy(),
                'motor_hw':  motor_target_hw.copy(),
                'joints': self.policy.joints,
                'init_pos': self.policy.initial_action_pose,
            })

        progress = self.replay_index / len(self.replay_pairs) * 100
        logger.info(f"Obs [{self.replay_index}:{len(self.replay_pairs)}] percent {progress:.2f}%")
        return True

    def run(self):
        logger.info(f"[RLSimWalk] starting playback→hardware loop... dt: {self.playback_dt}")
        # start hardware obs stream at our desired rate
        self.api.policyStart("default", dt=self.playback_dt)
        while True:
            msg_type, msg = self.api.receive()
            if msg_type == 'obs':
                if not self.handle_observation(msg):
                    break
            # ignore other messages
        logger.info("[RLSimWalk] loop ended")
        if self.save_obs:
            out = "hw_vs_sim.pkl"
            with open(out, "wb") as f:
                pickle.dump(self.saved_pairs, f)
            logger.info(f"[RLSimWalk] saved {len(self.saved_pairs)} hw↔sim records to {out}")


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Playback sim observations to real hardware, mix IMU/commands/phase from sim and record HW response")
    parser.add_argument("--onnx_model_path", type=str, required=True,
                        help="path to your ONNX policy file")
    parser.add_argument("--serial_port", type=str, default="/dev/puddleduck_ctrl",
                        help="serial port for motor commands")
    parser.add_argument("--playback_hz", type=float, default=1.0,
                        help="Hz at which to step through sim observations")
    parser.add_argument("--action_scale", type=float, default=0.25,
                        help="scale factor for policy outputs → joint-angle offsets")
    parser.add_argument("--vel_scale", type=float, default=0.05,
                        help="scale for velocity terms")
    parser.add_argument("--save_obs", action="store_true",
                        help="save sim vs hw observation pairs & actions")
    parser.add_argument("--replay_obs", type=str, required=True,
                        help="path to pickled list of sim observation vectors")
    args = parser.parse_args()

    walker = RLSimWalk(
        onnx_model_path  = args.onnx_model_path,
        serial_port      = args.serial_port,
        playback_hz      = args.playback_hz,
        action_scale     = args.action_scale,
        vel_scale        = args.vel_scale,
        save_obs         = args.save_obs,
        replay_obs_path  = args.replay_obs,
    )
    walker.run()
